class Particle {
  PVector loc;
  PVector speed;
  PVector acceleration;
  topspeed;
 function particles() {
    loc = new PVector(random(width), random(height));
    speed = new PVector(0, 0);
    topspeed=8;
  }

  function update() {
    PVector mouse = new PVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
    acceleration = PVector.sub(mouse, 0);
    acceleration.normalize();
    acceleration.mult(0.2);
    speed.add(acceleration);
    speed.limit(topspeed);
    loc.add(speed);
  }

  function display() {
    noStroke();
    fill(255);
    ellipse(this.x, y, 4, 4);
  }
}

